 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    silhouette = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 8]
    if not markers or not silhouette:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in markers), max(r for r, _ in markers)
    c0, c1 = min(c for _, c in markers), max(c for _, c in markers)
    key = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    # Rotate the key clockwise, as demonstrated.
    pattern = [list(row) for row in zip(*key[::-1])]
    sr0, sr1 = min(r for r, _ in silhouette), max(r for r, _ in silhouette)
    sc0, sc1 = min(c for _, c in silhouette), max(c for _, c in silhouette)
    bh, bw = sr1 - sr0 + 1, sc1 - sc0 + 1
    if bh % len(pattern) or bw % len(pattern[0]):
        return [row[:] for row in grid]
    th, tw = bh // len(pattern), bw // len(pattern[0])
    out = [row[:] for row in grid]
    for pr, row in enumerate(pattern):
        for pc, color in enumerate(row):
            if color == 0:
                continue
            for r in range(sr0 + pr * th, sr0 + (pr + 1) * th):
                for c in range(sc0 + pc * tw, sc0 + (pc + 1) * tw):
                    if grid[r][c] == 8:
                        out[r][c] = color
    return out
